package tw.sunnycoop.widget;
import android.app.*;import android.os.Bundle;import android.graphics.Color;import android.webkit.*;import android.widget.*;import android.view.View;import org.json.*;
public class CloudActivity extends Activity {
 private WebView web;private TextView status;private Spinner sites;private JSONArray choices;private boolean busy;
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.BLACK);int pad=(int)(12*getResources().getDisplayMetrics().density);root.setPadding(pad,pad,pad,pad);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(pad,pad+insets.getSystemWindowInsetTop(),pad,pad+insets.getSystemWindowInsetBottom());return insets;});setContentView(root);
  status=new TextView(this);status.setTextColor(Color.WHITE);status.setText("在下方登入與網頁相同帳號，先儲存雲端設定，再按同步。此登入與手機 Chrome 分開。只讀取資料，不會啟用監測或訂閱推播。");root.addView(status);
  Button sync=new Button(this);sync.setText("同步雲端設定與資料");sync.setOnClickListener(v->sync());root.addView(sync);sites=new Spinner(this);root.addView(sites);Button disconnect=new Button(this);disconnect.setText("登出並中斷雲端同步");disconnect.setOnClickListener(v->{CookieManager.getInstance().removeAllCookies(done->{CookieManager.getInstance().flush();CloudSync.prefs(this).edit().clear().apply();CoopWidget.prefs(this).edit().putBoolean("cloudMode",false).apply();CoopWidget.render(this);finish();});});root.addView(disconnect);Button select=new Button(this);select.setText("使用所選場區並返回");root.addView(select);select.setOnClickListener(v->{try{if(choices==null)throw new Exception();CloudSync.prefs(this).edit().putString("siteId",choices.getJSONObject(sites.getSelectedItemPosition()).getString("id")).apply();CloudSync.apply(this,new JSONObject(CloudSync.prefs(this).getString("data","{}")));CoopWidget.prefs(this).edit().putBoolean("cloudMode",true).apply();CoopWidget.render(this);CoopWidget.schedule(this);finish();}catch(Exception e){status.setText("請先登入並按同步");}});
  web=new WebView(this);web.setBackgroundColor(Color.BLACK);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
  web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest req){return !"https".equals(req.getUrl().getScheme());}});root.addView(web,new LinearLayout.LayoutParams(-1,0,1));web.loadUrl(CloudSync.ORIGIN+"/index.html");
 }
 private void sync(){if(busy)return;busy=true;status.setText("正在同步…");CookieManager.getInstance().flush();String cookie=CloudSync.cookies(),ua=web.getSettings().getUserAgentString();new Thread(()->{try{JSONObject data=CloudSync.fetch(cookie,ua);CloudSync.accept(this,data);CloudSync.prefs(this).edit().putString("ua",ua).apply();JSONArray a=data.getJSONObject("config").getJSONArray("sites");runOnUiThread(()->{choices=a;String[] names=new String[a.length()];int selected=0;for(int i=0;i<a.length();i++){names[i]=a.optJSONObject(i).optString("name");if(a.optJSONObject(i).optString("id").equals(CloudSync.prefs(this).getString("siteId","")))selected=i;}ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);sites.setAdapter(adapter);sites.setSelection(selected);status.setText("同步成功。選擇場區後按「使用所選場區並返回」。警戒門檻請在網頁編輯；資料時間以伺服器快照為準。");});}catch(Exception e){runOnUiThread(()->status.setText("同步失敗：請完成下方網站登入，確認已儲存雲端設定，再重試。若登入頁無法完成，請先使用本機模式。"));}finally{runOnUiThread(()->busy=false);}},"coop-cloud-login").start();}
 protected void onDestroy(){if(web!=null){web.stopLoading();web.destroy();}super.onDestroy();}
}
